def create_output_horizontal_flip():
    """Horizontal flip of each 2x3 section"""
    output = []

    # Process each row, handling sections with separators
    for r in range(8):
        output_row = []

        # Skip separator columns (3, 7, 11, 15)
        if r == 2 or r == 5:
            output.append([2]*19)
            continue

        # Add left section (cols 0-2), flipped horizontally
        for c in [2, 1, 0]:
            if r < 2:  # First section (rows 0-1)
                val = grid[r][c]
            elif r < 5:  # Second section (rows 3-4)
                # Map r to 0-1 locally
                local_r = r - 3
                val = grid[local_r + 3][c]
            else:  # Third section (rows 6-7)
                local_r = r - 6
                val = grid[local_r + 6][c]
            output_row.append(val)

        # Add separator columns
        for sep_col in [3, 7, 11, 15]:
            output_row.append(2)

        output.append(output_row)

    return output

def create_output_vertical_flip():
    """Vertical flip of each 2-row section"""
    output = []

    for r in range(8):
        output_row = []

        if r == 2 or r == 5:
            output.append([2]*19)
            continue

        for c in range(19):
            if c == 3 or c == 7 or c == 11 or c == 15:
                output_row.append(2)
            elif c == 0, 1, 2:  # Left section
                if r < 2:
                    val = grid[1-r][c]  # Within row pair 0-1
                elif r < 5:
                    val = grid[6-(r-3)][c]  # Within row pair 3-4 -> map 3->1, 4->0
                else:
                    val = grid[7-(r-6)][c]  # Within row pair 6-7
            elif c == 4, 5, 6:  # Mid1 section
                if r < 2:
                    val = grid[1-r][c]
                elif r < 5:
                    val = grid[6-(r-3)][c]
                else:
                    val = grid[7-(r-6)][c]
            elif c == 8, 9, 10:  # Mid2 section
                if r < 2:
                    val = grid[1-r][c]
                elif r < 5:
                    val = grid[6-(r-3)][c]
                else:
                    val = grid[7-(r-6)][c]
            elif c == 12, 13, 14:  # Mid3 section
                if r < 2:
                    val = grid[1-r][c]
                elif r < 5:
                    val = grid[6-(r-3)][c]
                else:
                    val = grid[7-(r-6)][c]
            elif c == 16, 17, 18:  # Right section
                if r < 2:
                    val = grid[1-r][c]
                elif r < 5:
                    val = grid[6-(r-3)][c]
                else:
                    val = grid[7-(r-6)][c]
            else:
                output_row.append(2)  # Shouldn't happen

        output.append(output_row)

    return output

